<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
saas_require_login();
$orgId=saas_require_organization();$tourId=saas_require_tour();$db=saas_db();$org=saas_current_organization();$tour=saas_current_tour();$user=saas_current_user();$error='';$ok='';
function dash_setting(PDO $db,int $tourId,string $key,string $default=''):string{$q=$db->prepare('SELECT setting_value FROM tour_settings WHERE tour_id=? AND setting_key=? LIMIT 1');$q->execute([$tourId,$key]);return (string)($q->fetchColumn()??$default);}
function dash_save_setting(PDO $db,int $tourId,string $key,string $value,string $type='TEXT'):void{$q=$db->prepare('INSERT INTO tour_settings(tour_id,setting_key,setting_value,value_type) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),value_type=VALUES(value_type)');$q->execute([$tourId,$key,$value,$type]);}
if($_SERVER['REQUEST_METHOD']==='POST'){try{saas_check_csrf();$action=(string)($_POST['action']??'');if($action==='save_note'){saas_require_permission('tour.edit');dash_save_setting($db,$tourId,'notes',trim((string)$_POST['notes']));saas_audit('tour.notes_updated','tour',$tourId);$ok='Tour note saved.';}elseif($action==='save_schedule'){saas_require_permission('tour.edit');dash_save_setting($db,$tourId,'schedule',trim((string)$_POST['schedule']));saas_audit('tour.schedule_updated','tour',$tourId);$ok='Tour schedule saved.';}}catch(Throwable $e){$error=$e->getMessage();}}
$notes=dash_setting($db,$tourId,'notes');$schedule=dash_setting($db,$tourId,'schedule');$banner=dash_setting($db,$tourId,'banner_image');$transport=dash_setting($db,$tourId,'default_transport','NONE');
$stats=['passengers'=>0,'paid'=>0,'expenses'=>0,'due'=>0,'rooms'=>0,'buses'=>0];
$q=$db->prepare("SELECT COUNT(*) FROM tour_passengers WHERE tour_id=? AND status<>'CANCELLED'");$q->execute([$tourId]);$stats['passengers']=(int)$q->fetchColumn();
$q=$db->prepare("SELECT COALESCE(SUM(p.amount),0) FROM payments p WHERE p.tour_id=?");$q->execute([$tourId]);$stats['paid']=(float)$q->fetchColumn();
$q=$db->prepare("SELECT COALESCE(SUM(e.amount),0) FROM expenses e WHERE e.tour_id=?");$q->execute([$tourId]);$stats['expenses']=(float)$q->fetchColumn();
$q=$db->prepare("SELECT COALESCE(SUM(tp.fee-tp.discount+(SELECT COALESCE(SUM(tpf.total_price),0) FROM tour_passenger_features tpf WHERE tpf.tour_passenger_id=tp.id AND tpf.status='SELECTED')),0) - COALESCE((SELECT SUM(p.amount) FROM payments p WHERE p.tour_passenger_id=tp.id),0) FROM tour_passengers tp WHERE tp.tour_id=? AND tp.status<>'CANCELLED'");$q->execute([$tourId]);$stats['due']=max(0,(float)$q->fetchColumn());
$q=$db->prepare("SELECT COUNT(*) FROM rooms WHERE tour_id=?");$q->execute([$tourId]);$stats['rooms']=(int)$q->fetchColumn();
$q=$db->prepare("SELECT COUNT(*) FROM buses WHERE tour_id=? AND status='ACTIVE'");$q->execute([$tourId]);$stats['buses']=(int)$q->fetchColumn();
$q=$db->prepare("SELECT b.*, (SELECT COUNT(*) FROM seats s WHERE s.bus_id=b.id) seat_count FROM buses b WHERE b.tour_id=? AND b.status='ACTIVE' ORDER BY b.id");$q->execute([$tourId]);$buses=$q->fetchAll();
$seatMaps=[];foreach($buses as $b){$sq=$db->prepare("SELECT s.id,s.seat_code,s.row_no,s.status,pa.tour_passenger_id,pp.full_name FROM seats s LEFT JOIN passenger_seat_assignments pa ON pa.seat_id=s.id AND pa.bus_id=s.bus_id LEFT JOIN tour_passengers tp ON tp.id=pa.tour_passenger_id AND tp.tour_id=? LEFT JOIN passenger_profiles pp ON pp.id=tp.passenger_profile_id WHERE s.bus_id=? ORDER BY s.row_no,s.id");$sq->execute([$tourId,(int)$b['id']]);$seatMaps[(int)$b['id']]=$sq->fetchAll();}
$q=$db->prepare("SELECT tp.id,pp.full_name,pp.phone,tp.fee,tp.discount,COALESCE((SELECT SUM(p.amount) FROM payments p WHERE p.tour_passenger_id=tp.id),0) paid FROM tour_passengers tp JOIN passenger_profiles pp ON pp.id=tp.passenger_profile_id WHERE tp.tour_id=? AND tp.status<>'CANCELLED' ORDER BY tp.registered_at DESC LIMIT 6");$q->execute([$tourId]);$recentPassengers=$q->fetchAll();
$baseUrl=rtrim((string)($config['app']['base_url']??''),'/');$publicUrl=$baseUrl.'/tour/'.rawurlencode((string)$tour['slug']);
?>
