{display:flex;gap:7px;min-width:0}.seat-aisle{min-width:28px;border-left:1px dashed #d0d5dd;border-right:1px dashed #d0d5dd;border-radius:6px}.dash-seat{border:1px solid #cfd4dc;border-radius:8px;min-height:43px;padding:4px;background:#eef2ff;font-size:11px;font-weight:800;text-align:center;cursor:pointer;position:relative;flex:1;min-width:0}.dash-seat small{display:block;font-size:8px;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:3px}.dash-seat[draggable=true]{cursor:grab}.dash-seat.dragging{opacity:.45}.dash-seat.drop-target{outline:3px dashed #155eef;outline-offset:2px}.dash-seat.occupied{background:#d1fadf;border-color:#86efac}.seat-layout-note{padding:8px 10px;background:#f8fafc;border:1px solid #eaecf0;border-radius:9px;font-size:11px;color:#667085;margin-bottom:10px}.seat-modal{display:none;position:fixed;inset:0;background:#0007;z-index:50;align-items:center;justify-content:center;padding:20px}.seat-modal.open{display:flex}.seat-modal-card{background:#fff;border-radius:16px;width:min(430px,100%);padding:20px;box-shadow:0 20px 60px #0004}.seat-modal-card h3{margin:0 0 6px}.seat-modal-card select{width:100%;padding:11px;border:1px solid #d0d5dd;border-radius:9px;margin:12px 0}.seat-modal-actions{display:flex;gap:8px;justify-content:flex-end}.seat-modal-actions button{padding:9px 12px;border:1px solid #d0d5dd;border-radius:9px;background:#fff;font-weight:800;cursor:pointer}.seat-modal-actions .primary{background:#155eef;color:#fff;border-color:#155eef}.dash-seat.occupied{background:#d1fadf;border-color:#86efac}.seat-actions{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-top:12px}.transport strong{display:block;font-size:16px}.muted{color:#667085;font-size:12px}.buslist{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin-top:12px}.bus{border:1px solid #e5e7eb;border-radius:12px;padding:12px}.bus strong{display:block}.empty{border:1px dashed #cfd6df;border-radius:13px;padding:24px;text-align:center}.note,.schedule{width:100%;min-height:110px;padding:11px;border:1px solid #d0d5dd;border-radius:10px;font:inherit;resize:vertical}.schedule{min-height:150px}.save{margin-top:8px}.list{display:grid;gap:8px}.person{display:flex;justify-content:space-between;gap:10px;padding:9px 0;border-bottom:1px solid #eef0f2}.person:last-child{border-bottom:0}.pill{background:#f2f4f7;padding:4px 7px;border-radius:99px;font-size:10px;font-weight:800;white-space:nowrap}.links{display:flex;gap:7px;flex-wrap:wrap}.alert{padding:11px;border-radius:10px;margin-bottom:15px}.ok{background:#ecfdf3;color:#067647}.err{background:#fef3f2;color:#b42318}@media(max-width:1050px){.stats{grid-template-columns:repeat(3,1fr)}.layout{grid-template-columns:1fr}}@media(max-width:700px){.side{position:static;width:100%;height:auto}.app{display:block}.main{margin-left:0;width:100%;padding:16px 12px}.stats{grid-template-columns:1fr 1fr}.buslist{grid-template-columns:1fr}.hero{min-height:200px;flex-direction:column;align-items:flex-start}}@media(max-width:450px){.stats{grid-template-columns:1fr}}
