<section class="panel"><div class="head"><div><h2>Bus seat plan</h2><div class="muted">Default transport: <?=saas_h($transport)?> · Click a seat to assign · Drag an occupied seat to change/swap</div></div><a class="btn green" href="buses.php">＋ Add new bus</a></div><?php if($transport==='BUS'):?><?php if(!$buses):?><div class="empty"><h3>No bus configured</h3><p class="muted">Create your first bus to see the seat plan here.</p><a class="btn green" href="buses.php">Create bus &amp; seats</a></div><?php else:?><div class="seat-tabs"><?php foreach($buses as $bi=>$b):?><button type="button" class="seat-tab <?=($bi===0?'active':'')?>" data-bus-tab="<?=((int)$b['id'])?>"><?=saas_h($b['name'])?></button><?php endforeach;?></div><?php foreach($buses as $bi=>$b):?><div class="seat-map bus-map" data-bus-map="<?=((int)$b['id'])?>" style="<?=($bi===0?'':'display:none')?>"><?php $rows=[];foreach(($seatMaps[(int)$b['id']]??[]) as $s)$rows[(int)$s['row_no']][]=$s;foreach($rows as $rn=>$items):$layout=strtolower(str_replace('x','+',trim((string)$b['layout_type'])));$parts=preg_split('/\s*\+\s*/',$layout);$leftCount=($rn===0)?count($items):((count($parts)>=2)?min(max(1,(int)$parts[0]),max(1,count($items)-1)):max(1,(int)ceil(count($items)/2)));$left=array_slice($items,0,$leftCount);$right=array_slice($items,$leftCount);?><div class="seat-row"><div class="seat-side"><?php foreach($left as $s):$occ=!empty($s['full_name']);?><button type="button" draggable="<?=$occ?'true':'false'?>" class="dash-seat <?=$occ?'occupied':''?>" data-seat-id="<?=((int)$s['id'])?>" data-passenger-id="<?=((int)($s['tour_passenger_id']??0))?>" data-seat-code="<?=saas_h($s['seat_code'])?>" title="<?=saas_h($occ?$s['full_name']:'Click to assign')?>"><?=saas_h($s['seat_code'])?><small><?=saas_h($occ?mb_substr($s['full_name'],0,12):'Available')?></small></button><?php endforeach;?></div><div class="seat-aisle"></div><div class="seat-side"><?php foreach($right as $s):$occ=!empty($s['full_name']);?><button type="button" draggable="<?=$occ?'true':'false'?>" class="dash-seat <?=$occ?'occupied':''?>" data-seat-id="<?=((int)$s['id'])?>" data-passenger-id="<?=((int)($s['tour_passenger_id']??0))?>" data-seat-code="<?=saas_h($s['seat_code'])?>" title="<?=saas_h($occ?$s['full_name']:'Click to assign')?>"><?=saas_h($s['seat_code'])?><small><?=saas_h($occ?mb_substr($s['full_name'],0,12):'Available')?></small></button><?php endforeach;?></div></div><?php endforeach;?><div class="seat-layout-note">Layout: <?=saas_h(strtoupper((string)$b['layout_type']))?> · Clear center aisle for 2×2, 1×2, 2×3 and similar layouts.</div><div class="seat-actions"><span class="muted"><?=count($seatMaps[(int)$b['id']]??[])?> seats</span><a class="btn primary" href="seat_plan.php?bus_id=<?=$b['id']?>">Open full seat plan</a></div></div><?php endforeach;?><?php endif;?><?php else:?><div class="empty"><h3>No bus seat plan</h3><p class="muted">Select BUS as the default transport to use a seat plan.</p></div><?php endif;?></section>
