<div class="seat-modal" id="seatModal"><div class="seat-modal-card"><h3>Assign passenger</h3><div class="muted" id="seatModalText">Choose a passenger for this seat.</div><select id="seatPassenger"><option value="">Select passenger</option><?php $allPassengers=$db->prepare("SELECT tp.id,pp.full_name,pp.phone FROM tour_passengers tp JOIN passenger_profiles pp ON pp.id=tp.passenger_profile_id WHERE tp.tour_id=? AND tp.status='ACTIVE' ORDER BY pp.full_name");$allPassengers->execute([$tourId]);foreach($allPassengers->fetchAll() as $ap):?><option value="<?=$ap['id']?>"><?=saas_h($ap['full_name'])?><?=!empty($ap['phone'])?' — '.saas_h($ap['phone']):''?></option><?php endforeach;?></select><div class="seat-modal-actions"><button type="button" id="seatModalCancel">Cancel</button><button type="button" class="primary" id="seatModalAssign">Assign seat</button></div></div></div>
</aside></div><script>const sb=document.getElementById("settingsBtn"),sm=document.getElementById("settingsMenu");if(sb)sb.addEventListener("click",()=>{const o=sm.classList.toggle("open");sb.setAttribute("aria-expanded",o?"true":"false")});document.querySelectorAll("[data-bus-tab]").forEach(b=>b.addEventListener("click",()=>{document.querySelectorAll(".seat-tab").forEach(x=>x.classList.remove("active"));document.querySelectorAll(".bus-map").forEach(x=>x.style.display="none");b.classList.add("active");const m=document.querySelector('[data-bus-map="'+b.dataset.busTab+'"]');if(m)m.style.display="block"}));const seatModal=document.getElementById("seatModal"),seatPassenger=document.getElementById("seatPassenger"),seatModalText=document.getElementById("seatModalText");let targetSeat=0,targetBus=0,dragSource=null;function openSeatModal(btn){targetSeat=Number(btn.dataset.seatId);targetBus=Number(btn.closest("[data-bus-map]")?.dataset.busMap||0);seatPassenger.value=btn.dataset.passengerId||"";seatModalText.textContent="Assign "+btn.dataset.seatCode+" to a passenger.";seatModal.classList.add("open");seatPassenger.focus()}function closeSeatModal(){seatModal?.classList.remove("open");targetSeat=0;targetBus=0}document.querySelectorAll(".dash-seat").forEach(btn=>{btn.addEventListener("click",()=>openSeatModal(btn));btn.addEventListener("dragstart",e=>{if(!btn.dataset.passengerId||btn.dataset.passengerId==="0")return;e.dataTransfer.effectAllowed="move";e.dataTransfer.setData("text/plain",btn.dataset.seatId);dragSource=btn;btn.classList.add("dragging")});btn.addEventListener("dragend",()=>{btn.classList.remove("dragging");document.querySelectorAll(".drop-target").forEach(x=>x.classList.remove("drop-target"));dragSource=null});btn.addEventListener("dragover",e=>{if(dragSource&&dragSource!==btn){e.preventDefault();btn.classList.add("drop-target")}});btn.addEventListener("dragleave",()=>btn.classList.remove("drop-target"));btn.addEventListener("drop",async e=>{e.preventDefault();btn.classList.remove("drop-target");if(!dragSource||dragSource===btn)return;const fd=new FormData();fd.append("csrf",<?=json_encode(saas_csrf())?>);fd.append("swap","1");fd.append("source_seat_id",dragSource.dataset.seatId);fd.append("target_seat_id",btn.dataset.seatId);try{const r=await fetch("seat_assign.php",{method:"POST",body:fd,credentials:"same-origin"});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||"Seat change failed.");location.reload()}catch(err){alert(err.message)}})});document.getElementById("seatModalAssign")?.addEventListener("click",async()=>{if(!targetSeat||!targetBus||!seatPassenger.value)return;const fd=new FormData();fd.append("csrf",<?=json_encode(saas_csrf())?>);fd.append("tour_passenger_id",seatPassenger.value);fd.append("bus_id",targetBus);fd.append("seat_id",targetSeat);try{const r=await fetch("seat_assign.php",{method:"POST",body:fd,credentials:"same-origin"});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||"Seat assignment failed.");closeSeatModal();location.reload()}catch(err){alert(err.message)}});document.getElementById("seatModalCancel")?.addEventListener("click",closeSeatModal);seatModal?.addEventListener("click",e=>{if(e.target===seatModal)closeSeatModal()});</script></body></html>